import (
	"io/ioutil"
	"path/filepath"
	"strings"
)

/**
Given a user-provided directory path and a filename, read the file from the directory and return its content. If any error occurs during the file reading process (e.g. file not found, permission error), return an empty string. The returned string will be freed by the caller.

@param filename The name of the file to read, requested by a user.
@param dir_path The path of the directory where the file is located.

@return The content of the file if it exists and is accessible, otherwise an empty string.
*/
func readFileFromDir(filename, dirPath string) string {
	// Basic sanitization to prevent common directory traversal attempts.
	// This is a first line of defense, but not exhaustive against all encoding tricks.
	if strings.Contains(filename, "..") || strings.Contains(filename, "/") || strings.Contains(filename, "\\") {
		return ""
	}
	if strings.Contains(dirPath, "..") || strings.Contains(dirPath, "/") || strings.Contains(dirPath, "\\") {
		return ""
	}

	// Construct the full path.
	fullPath := filepath.Join(dirPath, filename)

	// Canonicalize both paths to resolve any symbolic links or relative path components.
	// This helps in comparing them reliably.
	absDirPath, err := filepath.Abs(dirPath)
	if err != nil {
		return ""
	}
	absFullPath, err := filepath.Abs(fullPath)
	if err != nil {
		return ""
	}

	// Ensure the resolved full path is still within the intended directory.
	// This is a crucial step to prevent directory traversal.
	// We use HasPrefix on the canonicalized paths.
	if !strings.HasPrefix(absFullPath, absDirPath) {
		return ""
	}

	// Read the file content.
	content, err := ioutil.ReadFile(fullPath)
	if err != nil {
		// Return empty string on any error during file reading.
		return ""
	}

	// Return the file content as a string.
	return string(content)
}
